const S=1.1;const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};const h=Math.SQRT1_2;const Q={up:[-h,0,0,h],down:[h,0,0,h],right:[0,0,-h,h],left:[0,0,h,h]};
function pos(c,r){return [(c-1)*S,0.4,(1-r)*S];}
function dist(s){return Math.abs(2-s.c)+Math.abs(2-s.r);}
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:''};}
export function reduce({state,event}){if(event.type!=='action')return state;const s=state;const a=event.action;if(dist(s)===0)return {...s,msg:'Goal reached. Press Reset to play again.'};if(a==='hint'){const d=s.c<2?'right':s.c>2?'left':s.r<2?'up':'down';return {...s,hint:d,msg:'Hint: move '+d[0].toUpperCase()+d.slice(1)+'.'};}const v=D[a];if(!v)return s;const c=s.c+v[0],r=s.r+v[1];if(c<0||c>2||r<0||r>2)return {...s,msg:'That move would leave the board.'};return {c,r,moves:s.moves+1,hint:null,msg:''};}
export function evaluate({state}){const s=state||initialState();const p=pos(s.c,s.r);const d=dist(s);const nodes={token:{position:p},hintArrow:{visible:!!s.hint&&d>0,position:p,quaternion:Q[s.hint||'up']}};let goal;if(d===0){goal={status:'won',message:'You reached the goal in '+s.moves+' moves. The shortest route is 4 moves.'+(s.moves===4?' Perfect!':'')};}else{goal={status:'playing',message:s.msg||'Reach the orange goal square.'};}return {nodes,readouts:{moves:s.moves,dist:d},goal};}
